     6	import { loadRootDashboardConfig } from '../../OotbOmt/loadRootDashboardConfig';
     7	import PageSkeleton from '../../../common/PageSkeleton';
     8	import type { IDashboardProps } from './IDashboardProps';
     9	
    10	export default function DashboardComponent({ props }: IDashboardProps): React.ReactElement {
    11	  const [rows, setRows] = React.useState<any[]>([]);
    12	  const [loading, setLoading] = React.useState(true);
    13	
    14	  React.useEffect(() => {
    15	    void loadData();
    16	  }, []);
    17	
    18	  const loadData = async () => {
    19	    try {
    20	      const siteUrl =
    21	        props?.Context?.pageContext?.web?.absoluteUrl ||
    22	        props?.siteUrl ||
    23	        '';
    24	      const userId: number = props?.Context?.pageContext?.legacyPageContext?.userId;
    25	
    26	      const rootCfg = await loadRootDashboardConfig({
    27	        siteUrl,
    28	        smartMetadataListId: props?.SmartMetadataListID,
    29	      });
    30	
    31	      const sites: any[] = rootCfg?.rootSiteData || [];
    32	      const taskFetchStart = moment().subtract(90, 'days').startOf('day').toISOString();
    33	      const filter = `(Modified ge '${taskFetchStart}') and (PercentComplete le 0.90)`;
    34	
    35	      const siteResults = await Promise.all(
    36	        sites.map((site: any) =>
    37	          globalCommon.loadAllSiteTaskData(site, filter).catch(() => [] as any[])
    38	        )
    39	      );
    40	
    41	      const allTasks: any[] = ([] as any[]).concat(...siteResults);
    42	      const today = moment().format('DD/MM/YYYY');
    43	
    44	      const todayTasks = allTasks.filter((item: any) => {
    45	        try {
    46	          const workingAction: any[] = Array.isArray(item.WorkingAction)
    47	            ? item.WorkingAction
    48	            : (globalCommon.parseJSON(item.WorkingAction) || []);
    49	          const workingDetails = workingAction.find((wa: any) => wa.Title === 'WorkingDetails');
    50	          return (
    51	            workingDetails?.InformationData?.some((info: any) =>
    52	              info.WorkingDate === today &&
    53	              Array.isArray(info.WorkingMember) &&
    54	              info.WorkingMember.some((member: any) => member.Id == userId)
    55	            ) ?? false
    56	          );
    57	        } catch {
    58	          return false;
    59	        }
    60	      });
    61	
    62	      const enriched = todayTasks.map((item: any) => {
    63	        const workingAction: any[] = Array.isArray(item.WorkingAction)
    64	          ? item.WorkingAction
    65	          : (globalCommon.parseJSON(item.WorkingAction) || []);
    66	        const workingDetails = workingAction.find((wa: any) => wa.Title === 'WorkingDetails');
    67	        const todayInfo = workingDetails?.InformationData?.find(
    68	          (info: any) => info.WorkingDate === today
    69	        );
    70	        const team: string =
    71	          todayInfo?.WorkingMember?.map((m: any) => m.Title)
    72	            .filter(Boolean)
    73	            .join(', ') ?? '';
    74	
    75	        // PercentComplete is already 0-100 after processTask in globalCommon
    76	        const rawPc = Number(item.PercentComplete ?? 0);
    77	        const pc = rawPc > 1 ? rawPc : rawPc * 100;
    78	        const status =
    79	          pc >= 90 ? 'Completed' : pc > 0 ? 'In Progress' : 'Not Started';
    80	
    81	        return {
    82	          ...item,
    83	          _status: status,
    84	          _team: team,
    85	          _createdBy: `${moment(item.Created).format('DD/MM/YYYY')} — ${item.Author?.Title || ''}`,
    86	          _modifiedBy: `${moment(item.Modified).format('DD/MM/YYYY')} — ${item.Editor?.Title || ''}`,
    87	        };
    88	      });
    89	
    90	      setRows(enriched);
    91	    } catch (e) {
    92	      console.error('[Dashboard] loadData failed', e);
    93	    } finally {
    94	      setLoading(false);
    95	    }
    96	  };
    97	
    98	  const columns = React.useMemo<ColumnDef<any, unknown>[]>(
    99	    () => [
   100	      {
   101	        accessorFn: (row) => row?.Title,
   102	        id: 'Title',
   103	        placeholder: 'Title',
   104	        header: '',
   105	        size: 280,
   106	        resetColumnFilters: false,
   107	        resetSorting: false,
   108	        cell: ({ getValue }) => (
   109	          <span className="font-semibold text-[13px]" style={{ color: 'var(--SiteColor, #2F5596)' }}>
   110	            {String(getValue() ?? '')}
   111	          </span>
   112	        ),
   113	      },
   114	      {
   115	        accessorFn: (row) => row?._status,
   116	        id: 'Status',
   117	        placeholder: 'Status',
   118	        header: '',
   119	        size: 110,
   120	        resetColumnFilters: false,
   121	        resetSorting: false,
   122	        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
   123	      },
   124	      {
   125	        accessorFn: (row) => row?.ProjectTitle,
   126	        id: 'Project',
   127	        placeholder: 'Project',
   128	        header: '',
   129	        size: 200,
   130	        resetColumnFilters: false,
   131	        resetSorting: false,
   132	        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
   133	      },
   134	      {
   135	        accessorFn: (row) => row?.PortfolioTitle,
   136	        id: 'Portfolio',
   137	        placeholder: 'Portfolio',
   138	        header: '',
   139	        size: 200,
   140	        resetColumnFilters: false,
   141	        resetSorting: false,
   142	        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
   143	      },
   144	      {
   145	        accessorFn: (row) => row?._team,
   146	        id: 'Team',
   147	        placeholder: 'Team',
   148	        header: '',
   149	        size: 180,
   150	        resetColumnFilters: false,
   151	        resetSorting: false,
   152	        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
   153	      },
   154	      {
   155	        accessorFn: (row) => row?.Categories,
   156	        id: 'Category',
   157	        placeholder: 'Category',
   158	        header: '',
   159	        size: 120,
   160	        resetColumnFilters: false,
   161	        resetSorting: false,
   162	        cell: ({ getValue }) => <span>{String(getValue() ?? '')}</span>,
   163	      },
   164	      {
   165	        accessorFn: (row) => row?._createdBy,
   166	        id: 'CreatedBy',
   167	        placeholder: 'Created By',
   168	        header: '',
   169	        size: 190,
   170	        resetColumnFilters: false,
   171	        resetSorting: false,
   172	        cell: ({ getValue }) => (
   173	          <span className="text-xs text-slate-600">{String(getValue() ?? '')}</span>
   174	        ),
   175	      },
   176	      {
   177	        accessorFn: (row) => row?._modifiedBy,
   178	        id: 'ModifiedBy',
   179	        placeholder: 'Modified By',
   180	        header: '',
   181	        size: 190,
   182	        resetColumnFilters: false,
   183	        resetSorting: false,
   184	        cell: ({ getValue }) => (
   185	          <span className="text-xs text-slate-600">{String(getValue() ?? '')}</span>
   186	        ),
   187	      },
   188	    ],
   189	    []
   190	  );
   191	
   192	  if (loading) {
   193	    return <PageSkeleton variant="default" />;
   194	  }
   195	
   196	  return (
   197	    <div className="w-full min-w-0 bg-white flex flex-col px-4 pt-3 pb-6 min-h-screen">
   198	      <div className="sticky top-0 z-40 bg-white pb-2">
   199	        <h2
   200	          className="text-xl font-bold mb-3"
   201	          style={{ color: 'var(--SiteColor, #2f5596)' }}
   202	        >
   203	          {"Today's Working Tasks"}
   204	        </h2>
   205	      </div>
   206	      {rows.length === 0 ? (
   207	        <div className="text-sm text-slate-500 mt-8 text-center">
   208	          No tasks assigned to you for today.
   209	        </div>
   210	      ) : (
   211	        <GlobalCommanTable
   212	          columns={columns}
   213	          data={rows}
   214	          paginatedTable={false}
   215	          pageName="Dashboard"
   216	          showHeader={true}
   217	          showRestructureButton={false}
   218	          showCreationAllButton={false}
   219	        />
   220	      )}
   221	    </div>
   222	  );
   223	}

